import {collectMaterials,materialNotation} from '/material-model.js';
import {artworkURL,isSavedArtwork} from '/artwork.js';
import {patchCreationList} from '/stable-dom.js';
import {readABCText} from '/abc-material.js';
import {api,openCloudState,saveCloudState,flushCloudState} from '/cloud-state.js';
import {storeAudio,readAudio,audioURL} from '/training-audio-store.js';
import {uploadedAudioAssets} from '/voice-library.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const svg=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const size=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(0)+' KB':(n/1048576).toFixed(1)+' MB';
export function initUploads({toast,onPlay,isPlaying,onPreviewABC,onChange,getDrafts=()=>[],getGenerationSeen=()=>[],onRemoveDraft,onRenameDraft,onPurgedAsset}){
 const root=document.querySelector('#uploads-content');let assets=[],meta={items:[]},query='',sort='newest',trash=false,loaded=false,busy=false,error='',queue=[],origin='all',typeFilter='all';
 root.innerHTML=`<div class="view-heading"><div><span class="micro-label">YOUR PERSONAL MATERIAL ARCHIVE</span><h2>素材管理</h2><p>创作的声音、收藏的乐谱，在这里汇集。上传素材与生成作品统一管理。</p></div><button class="primary-button" id="upload-pick">${svg('upload')}上传素材</button></div><div class="upload-summary"><div class="glass"><span>音乐素材</span><strong id="upload-music-count">0</strong><small>旋律、完整歌曲与伴奏</small></div><div class="glass"><span>语音素材</span><strong id="upload-speech-count">0</strong><small>对白、旁白与音色参考</small></div><div class="glass"><span>ABC 乐谱</span><strong id="upload-abc-count">0</strong><small>旋律、曲谱与编曲参考</small></div><div class="glass"><span>素材空间</span><strong id="upload-size">0 MB</strong><small>文件保存在你的云端空间</small></div></div><div class="material-source-filters" role="group" aria-label="素材来源"><button type="button" data-material-origin="all" aria-pressed="true">全部素材</button><button type="button" data-material-origin="generated" aria-pressed="false">我的生成</button><button type="button" data-material-origin="uploaded" aria-pressed="false">我的上传</button></div><div class="upload-toolbar"><select id="material-type" aria-label="素材类型"><option value="all">所有类型</option><option value="music">音乐</option><option value="speech">语音</option><option value="abc">ABC 乐谱</option><option value="sounds">音效</option></select><label class="upload-search glass">${svg('search')}<input id="upload-search" type="search" placeholder="搜索素材名称…" aria-label="搜索素材"></label><select id="upload-sort" aria-label="素材排序"><option value="newest">最近添加</option><option value="name">名称顺序</option><option value="size">文件大小</option></select></div><button class="upload-drop glass" id="upload-drop"><span class="upload-drop-icon">${svg('upload')}</span><strong>把声音与乐谱收藏在这里</strong><span>拖入音乐、语音或 ABC 乐谱，或点击上传</span></button><input id="upload-files" type="file" accept=".wav,.mp3,.flac,.m4a,.ogg,.aac,.abc,.txt,.md" multiple hidden><div id="upload-queue" role="status" aria-live="polite"></div><div class="upload-list-heading"><span id="upload-list-label">全部素材</span><span id="upload-result-count"></span></div><div id="upload-list"></div><p class="upload-footnote">双击播放，拖入左侧回收站或使用删除按钮。上传与生成的素材都可在回收站恢复。</p><dialog id="upload-rename-dialog" class="upload-dialog glass"><form method="dialog"><h3>编辑素材名称</h3><label>显示名称<input id="upload-new-name" maxlength="120" required></label><p>原始文件与下载文件名保持不变。</p><div><button value="cancel" class="outline-button">取消</button><button value="save" class="primary-button">保存</button></div></form></dialog><dialog id="upload-confirm-dialog" class="upload-dialog glass"><form id="upload-confirm-form"><span class="micro-label">ADD TO YOUR COLLECTION</span><h3>收藏新素材</h3><p id="upload-confirm-count"></p><label id="upload-audio-kind-field">这些音频属于<select id="upload-audio-kind"><option value="music">音乐 · 歌曲、旋律与伴奏</option><option value="speech">语音 · 对白、旁白与音色参考</option></select></label><p>ABC、TXT 与 MD 乐谱会自动归档为 ABC。音频最多 100 MB，乐谱最多 200 KB / 50000 字符。</p><div><button type="button" id="upload-cancel" class="outline-button">取消</button><button type="submit" class="primary-button">上传并收藏</button></div></form></dialog>`;
 const assetType=a=>a.kind.slice(7),label=a=>({music:'音乐',speech:'语音',abc:'ABC 乐谱'})[assetType(a)];
 const $=s=>root.querySelector(s),item=id=>meta.items.find(i=>i.id===id),title=a=>item(a.id)?.name||a.title||a.name;
 function update(id,patch){let m=item(id);if(!m){m={id};meta.items.push(m);}Object.assign(m,patch);saveCloudState('uploads',meta);window.dispatchEvent(new CustomEvent('sanzo-cloud-update',{detail:{namespace:'uploads',data:meta}}));render();}
 const entries=()=>collectMaterials(assets,getDrafts(),meta,getGenerationSeen()),entry=id=>entries().find(a=>a.id===id);
 function card(a){
  const type=a.type,score=type==='abc',playing=!!a.audioURL&&isPlaying(a.id),art=isSavedArtwork(a.art)?artworkURL(a.art):'';
  const visual=art&&type==='music'?'<img class="material-cover" src="'+art+'" alt="" loading="lazy" decoding="async">':score?'<div class="upload-score-lines" aria-hidden="true"><span>♩</span><span>♫</span><span>♪</span></div>':'<div class="upload-signal" aria-hidden="true">'+Array.from({length:29},(_,i)=>'<i style="--bar:'+ (18+((i*17+type.length*13)%65)) +'%"></i>').join('')+'</div>';
  return '<article class="upload-file glass '+type+(playing?' is-playing':'')+'" data-creation-id="'+esc(a.id)+'" data-material-id="'+esc(a.id)+'" draggable="true"><div class="upload-art '+type+'"><span class="upload-type-badge">'+svg(score?'score':type==='speech'?'voice':'music')+({music:'音乐',speech:'语音',abc:'ABC 乐谱',sounds:'音效'})[type]+'</span>'+visual+'<button class="upload-file-play '+type+'" '+(a.audioURL?'data-upload-play':'data-upload-preview')+'="'+esc(a.id)+'" aria-label="'+(a.audioURL?playing?'暂停':'播放':'预览乐谱')+' '+esc(a.title)+'">'+svg(a.audioURL?playing?'pause':'play':'score')+'<span>'+(a.audioURL?playing?'正在播放':'播放音频':'预览乐谱')+'</span></button></div><div class="upload-file-info"><span class="material-origin '+a.origin+'">'+(a.origin==='generated'?'我的生成':'我的上传')+'</span><h3 title="'+esc(a.title)+'">'+esc(a.title)+'</h3><p>'+(a.notation?'ABC':esc((a.name||'').split('.').pop()?.toUpperCase()||'音频'))+'<span class="upload-dot">·</span>'+(a.bytes?size(a.bytes):'乐谱文本')+'</p><span class="upload-date">'+(a.created_at?esc(new Date(a.created_at).toLocaleDateString('zh-CN')):'已保存到云端')+'</span></div><div class="upload-file-actions"><button data-upload-rename="'+esc(a.id)+'" aria-label="重命名 '+esc(a.title)+'" title="重命名">'+svg('create')+'</button><button data-upload-download="'+esc(a.id)+'" aria-label="下载 '+esc(a.title)+'" title="下载"><svg viewBox="0 0 24 24"><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/></svg></button><button data-upload-remove="'+esc(a.id)+'" aria-label="移入回收站 '+esc(a.title)+'" title="移入回收站">'+svg('trash')+'</button></div></article>';
 }
 function render(){onChange?.();
  const visible=entries();$('#upload-music-count').textContent=visible.filter(a=>a.type==='music').length;$('#upload-speech-count').textContent=visible.filter(a=>a.type==='speech').length;$('#upload-abc-count').textContent=visible.filter(a=>a.type==='abc').length;$('#upload-size').textContent=size(assets.reduce((n,a)=>n+a.bytes,0));
  $('#upload-pick').innerHTML=svg('upload')+(busy?'上传中…':'上传素材');$('#upload-pick').disabled=busy;$('#upload-drop').disabled=busy;
  $('#upload-list-label').textContent=trash?'素材回收站':'全部素材';
  const list=visible.filter(a=>(origin==='all'||a.origin===origin)&&(typeFilter==='all'||a.type===typeFilter)&&a.title.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?title(a).localeCompare(title(b),'zh'):sort==='size'?b.bytes-a.bytes:(b.created_at||'').localeCompare(a.created_at||''));
  $('#upload-result-count').textContent=list.length+' 项素材';
  $('#upload-queue').innerHTML=queue.map(q=>`<div class="upload-queue-item"><span>${esc(q.name)}</span><small class="${q.failed?'failed':''}">${esc(q.status)}</small></div>`).join('');
  const markup=error?`<div class="upload-empty glass"><h3>暂时无法加载素材</h3><p>${esc(error)}</p><button id="upload-retry" class="outline-button">重新加载</button></div>`:!loaded?'<div class="upload-empty glass">正在读取云端素材…</div>':!list.length?`<div class="upload-empty glass">${svg('upload')}<h3>${query?'没有找到匹配的素材':trash?'回收站是空的':'还没有收藏素材'}</h3><p>${query?'试试其他关键词。':trash?'移除的素材会放在这里，可随时恢复。':'上传第一份素材，或前往创作空间生成音乐与语音。'}</p></div>`:list.map(card).join('');patchCreationList($('#upload-list'),markup);
 }
 async function load(){error='';render();try{const [data,state]=await Promise.all([api('/api/assets'),openCloudState('uploads',{items:[]})]);assets=(data.assets||[]).filter(a=>!a.status||a.status==='ready');meta=state;meta.items??=[];loaded=true;}catch(e){error=e.message;}render();}
 async function upload(files,audioKind){if(busy||!files.length)return;if(files.length>20){toast('每次最多上传 20 个文件。');return;}busy=true;queue=Array.from(files,f=>({name:f.name,status:'等待上传'}));render();for(let i=0;i<files.length;i++){const file=files[i],kind=/\.(abc|txt|md)$/i.test(file.name)?'upload-abc':'upload-'+audioKind;try{if(kind==='upload-abc'){if(!/\.(abc|txt|md)$/i.test(file.name)||!file.size||file.size>200000)throw Error('请选择不超过 200 KB 的 ABC、TXT 或 MD 乐谱');readABCText(new Uint8Array(await file.arrayBuffer()));}else if(!/\.(wav|mp3|flac|m4a|ogg|aac)$/i.test(file.name)||!file.size||file.size>100*1048576)throw Error('格式不支持或文件超过 100 MB');queue[i].status='正在上传…';render();const id='upload-'+crypto.randomUUID();await storeAudio(id,file,kind);assets.unshift({id,name:file.name,mime:file.type,bytes:file.size,kind,created_at:new Date().toISOString()});if(kind!=='upload-abc')window.dispatchEvent(new CustomEvent('sanzo-audio-upload',{detail:assets[0]}));queue[i].status='已保存到云端';}catch(e){queue[i].status=e.message;queue[i].failed=true;}render();}busy=false;render();toast('上传完成：'+queue.filter(q=>!q.failed).length+' 个成功，'+queue.filter(q=>q.failed).length+' 个失败。');}
 let staged=[];
 function stage(files){if(busy||!files.length)return;if(files.length>20){toast('每次最多上传 20 个文件。');return;}staged=files;const scores=files.filter(f=>/\.(abc|txt|md)$/i.test(f.name)).length;$('#upload-confirm-count').textContent=files.length+' 个文件 · '+size(files.reduce((n,f)=>n+f.size,0))+(scores?' · '+scores+' 份乐谱':'');$('#upload-audio-kind-field').hidden=scores===files.length;$('#upload-confirm-dialog').showModal();}
 $('#upload-cancel').onclick=()=>$('#upload-confirm-dialog').close();$('#upload-confirm-form').onsubmit=e=>{e.preventDefault();const files=staged;staged=[];$('#upload-confirm-dialog').close();upload(files,$('#upload-audio-kind').value);};
 $('#upload-pick').onclick=$('#upload-drop').onclick=()=>$('#upload-files').click();$('#upload-files').onchange=e=>{stage(Array.from(e.target.files));e.target.value='';};
 $('#upload-drop').ondragover=e=>{e.preventDefault();if(!busy)e.currentTarget.classList.add('dragging');};$('#upload-drop').ondragleave=e=>e.currentTarget.classList.remove('dragging');$('#upload-drop').ondrop=e=>{e.preventDefault();e.currentTarget.classList.remove('dragging');stage(Array.from(e.dataTransfer.files));};
 $('#material-type').onchange=e=>{typeFilter=e.target.value;render();};root.querySelectorAll('[data-material-origin]').forEach(b=>b.onclick=()=>{origin=b.dataset.materialOrigin;root.querySelectorAll('[data-material-origin]').forEach(item=>item.setAttribute('aria-pressed',String(item===b)));render();});
 $('#upload-search').oninput=e=>{query=e.target.value;render();};$('#upload-sort').onchange=e=>{sort=e.target.value;render();};
 let renameId=null;$('#upload-rename-dialog').addEventListener('close',()=>{if($('#upload-rename-dialog').returnValue==='save'&&$('#upload-new-name').value.trim()){const a=entry(renameId),value=$('#upload-new-name').value.trim();if(a?.source==='draft'){onRenameDraft?.(a.id,value.slice(0,60));render();}else update(renameId,{name:value});}});
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='upload-retry')load();if(b.dataset.uploadPreview){try{const a=entry(b.dataset.uploadPreview);if(!a)return;const text=a.notation||readABCText(new Uint8Array(await(await readAudio(a.assetId)).arrayBuffer()));await onPreviewABC({name:a.title,text,draft:a.draft});}catch(err){toast(err.message);}return;}if(b.dataset.uploadPlay){onPlay(b.dataset.uploadPlay);return;}if(b.dataset.uploadRemove){if(isPlaying(b.dataset.uploadRemove))onPlay(b.dataset.uploadRemove);remove(b.dataset.uploadRemove);}if(b.dataset.uploadRestore)update(b.dataset.uploadRestore,{trashed:false});if(b.dataset.uploadRename){renameId=b.dataset.uploadRename;$('#upload-new-name').value=entry(renameId)?.title||'';$('#upload-rename-dialog').showModal();}if(b.dataset.uploadDownload){try{const a=entry(b.dataset.uploadDownload);if(!a)return;const blob=a.assetId?await readAudio(a.assetId):new Blob([a.notation],{type:'text/plain'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=(a.title||a.name).replace(/[\\/:*?"<>|]/g,'_')+(a.notation?'.abc':'.'+(a.name||'audio.mp3').split('.').pop());link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){toast(err.message);}}});
 window.addEventListener('sanzo-cloud-update',e=>{if(e.detail.namespace==='uploads'){meta=e.detail.data;meta.items??=[];render();}else if(e.detail.namespace==='workspace')render();});
 window.addEventListener('sanzo-audio-upload',e=>{if(!assets.some(a=>a.id===e.detail.id))assets.unshift(e.detail);render();});
 function remove(id){const a=entry(id);if(!a)return;if(isPlaying(id))onPlay(id);if(a.source==='draft')onRemoveDraft?.(id);else update(id,{trashed:true,removedAt:Date.now()});render();toast('已移入素材管理回收站，可以恢复。');}
 async function purge(ids){await flushCloudState('uploads');let failed=0;for(const id of ids){if(!item(id)?.trashed)continue;try{const result=await api('/api/assets/'+encodeURIComponent(id),{method:'DELETE'});onPurgedAsset?.(result);assets=assets.filter(a=>a.id!==id);}catch(e){if(e.status===404)assets=assets.filter(a=>a.id!==id);else failed++;}}render();window.dispatchEvent(new CustomEvent('sanzo-cloud-update',{detail:{namespace:'uploads',data:meta}}));return failed;}
 return {show:()=>load(),forget:ids=>{assets=assets.filter(a=>!ids.includes(a.id));render();},refresh:render,has:id=>!!entry(id),remove,trashItems:()=>assets.filter(a=>item(a.id)?.trashed).map(a=>({...a,title:title(a)})),restore:id=>update(id,{trashed:false}),purge,
tracks:()=>entries().filter(a=>a.source==='asset'&&a.audioURL).map(a=>({id:a.id,title:a.title,type:a.type==='music'?'songs':a.type,artist:a.origin==='uploaded'?'我的上传':'我的生成',uploaded:a.origin==='uploaded',art:a.art,audioURL:a.audioURL,duration:120,tags:[],lyrics:'',prompt:'',style:a.type==='music'?'音乐素材':'语音素材'}))};
}
